message.content:
这是为您生成的一页研究开题评审汇报封面，采用暖米白底配合静谧的点阵与几何装饰，突出主标题与副标题信息。页面明确标注虚构测评材料属性，并预留日期占位，适合正式场合展示。
```html
<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8"/>
<title>虚构隔振支架研究开题</title>
<style>
  html,body{margin:0;padding:0;width:1920px;height:1080px;overflow:hidden;background:#F5F2E9;}
  *{box-sizing:border-box;}
  :root{
    --bg:#F5F2E9;
    --surface:#F3F0E7;
    --ink:#1B2620;
    --muted:#5C665D;
    --primary:#4F5E43;
    --secondary:#B4914A;
    --tertiary:#8C9FB2;
    --line:#A3AC9E;
    --font-serif:"Songti SC","Source Han Serif SC","Noto Serif CJK SC",Georgia,"Times New Roman",serif;
    --font-sans:"PingFang SC","Hiragino Sans GB","Microsoft YaHei","Helvetica Neue",Arial,sans-serif;
  }
  .slide{
    position:relative;width:1920px;height:1080px;overflow:hidden;
    background:var(--bg);color:var(--ink);font-family:var(--font-sans);
  }
  /* ---------- background field ---------- */
  .bg-field{
    position:absolute;inset:0;z-index:0;
    background:
      radial-gradient(1100px 780px at 2% 0%,rgba(180,145,74,.10),transparent 70%),
      radial-gradient(880px 760px at 52% 52%,rgba(140,159,178,.10),transparent 70%),
      radial-gradient(950px 760px at 96% 96%,rgba(79,94,67,.11),transparent 72%),
      linear-gradient(168deg,#F8F5EC 0%,#F5F2E9 52%,#EFECE1 100%);
  }
  .bg-field:after{
    content:"";position:absolute;inset:0;
    background:repeating-linear-gradient(90deg,rgba(27,38,32,.042) 0 1px,transparent 1px 160px);
  }
  .dot-field{position:absolute;z-index:1;background-image:radial-gradient(circle,rgba(27,38,32,.42) 1.05px,transparent 1.15px);background-size:15px 15px;}
  .dot-a{left:1090px;top:0;width:540px;height:150px;opacity:.34;}
  .dot-b{left:700px;top:836px;width:940px;height:244px;opacity:.20;}

  .prism{
    position:absolute;z-index:1;left:748px;top:-260px;width:170px;height:1520px;
    transform:rotate(17deg);
    background:linear-gradient(180deg,rgba(140,159,178,.22),rgba(140,159,178,.07) 72%,rgba(140,159,178,0));
  }
  .prism:after{content:"";position:absolute;left:94px;top:0;width:72px;height:1520px;background:rgba(255,255,255,.36);}

  .edge-prism{position:absolute;z-index:1;left:1846px;top:170px;width:420px;height:1200px;transform:rotate(15deg);transform-origin:top left;opacity:.92;}
  .edge-prism span{position:absolute;top:0;height:1200px;}
  .edge-prism .p1{left:0;width:64px;background:rgba(140,159,178,.18);}
  .edge-prism .p2{left:118px;width:34px;background:rgba(180,145,74,.16);}

  .gridline{position:absolute;z-index:2;top:0;width:1px;height:1080px;background:rgba(27,38,32,.05);}
  .gl1{left:480px;}.gl2{left:960px;}.gl3{left:1440px;}

  .top-rule{position:absolute;left:96px;top:48px;width:1760px;height:1px;z-index:6;background:rgba(27,38,32,.34);}
  .left-rule{position:absolute;left:60px;top:40px;width:1px;height:1000px;z-index:6;background:rgba(27,38,32,.24);}
  .rail-tick{position:absolute;left:54px;width:13px;height:1px;z-index:7;background:rgba(27,38,32,.42);}
  .rail-tick.t1{top:104px;}.rail-tick.t2{top:452px;}.rail-tick.t3{top:900px;}

  /* ---------- small meta ---------- */
  .top-meta{
    position:absolute;left:98px;top:60px;z-index:15;
    font-size:15px;font-weight:600;letter-spacing:4.4px;color:#4f5b53;
  }
  .top-right-meta{
    position:absolute;right:98px;top:60px;z-index:15;
    font-size:14px;font-weight:600;letter-spacing:3.6px;color:#6b756b;
  }
  .rail-label{
    position:absolute;left:46px;top:560px;width:420px;height:24px;z-index:15;
    transform:rotate(-90deg);transform-origin:left top;
    font-size:13px;font-weight:600;letter-spacing:5.2px;color:#637067;white-space:nowrap;
  }

  /* ---------- register (top-right) ---------- */
  .register{position:absolute;right:-70px;top:-70px;width:280px;height:280px;z-index:4;border-radius:50%;border:1px solid rgba(27,38,32,.36);}
  .register .r2{position:absolute;inset:12px;border-radius:50%;border:1px solid rgba(27,38,32,.18);}
  .register .r3{position:absolute;inset:28px;border-radius:50%;
    background:conic-gradient(from 210deg,rgba(79,94,67,.20),rgba(79,94,67,0) 24%,rgba(140,159,178,.30) 50%,rgba(140,159,178,.08) 78%,rgba(79,94,67,.20));}
  .register .r4{position:absolute;inset:38px;border-radius:50%;background:rgba(245,242,233,.9);border:1px solid rgba(27,38,32,.08);}
  .register .r5{position:absolute;inset:56px;border-radius:50%;background:rgba(140,159,178,.24);border:1px solid rgba(27,38,32,.09);}
  .register .dot{position:absolute;left:52px;top:180px;width:14px;height:14px;border-radius:50%;background:var(--secondary);box-shadow:0 0 0 5px rgba(180,145,74,.14);}

  /* ---------- title block ---------- */
  .title-block{position:absolute;left:140px;top:296px;z-index:20;width:1120px;}
  .kicker{
    display:flex;align-items:center;gap:18px;
    font-size:16px;font-weight:700;letter-spacing:6px;color:var(--primary);text-transform:uppercase;
  }
  .kicker .bar{width:64px;height:2px;background:var(--secondary);}
  h1{
    margin:34px 0 0 0;
    font-family:var(--font-serif);
    font-size:126px;line-height:1.14;font-weight:700;
    letter-spacing:2px;color:#18221D;
  }
  h1 .ln{display:block;}
  h1 .accent{color:#3C4A36;}
  .subline{
    margin-top:44px;display:flex;align-items:center;gap:26px;
  }
  .subline .rule{width:180px;height:1px;background:rgba(27,38,32,.42);}
  .subline .sub{
    font-size:31px;font-weight:600;letter-spacing:9px;color:#3E4A41;
  }
  .divider{margin-top:56px;width:820px;height:1px;background:rgba(27,38,32,.22);}

  /* ---------- notes ---------- */
  .notes{position:absolute;left:140px;top:806px;z-index:20;width:1180px;display:flex;gap:0;}
  .note{
    flex:1;padding-left:22px;border-left:1px solid rgba(27,38,32,.26);
  }
  .note:first-child{padding-left:0;border-left:none;}
  .note .n-idx{
    font-family:var(--font-serif);font-size:15px;font-weight:700;letter-spacing:3px;color:var(--secondary);
  }
  .note .n-txt{
    margin-top:12px;font-size:20px;line-height:1.62;color:#48534A;letter-spacing:.6px;
  }
  .dot-sep{width:1px;}

  /* ---------- date / page no ---------- */
  .date-chip{
    position:absolute;left:140px;top:690px;z-index:20;
    display:flex;align-items:center;gap:16px;
    padding:13px 26px;border:1px solid rgba(27,38,32,.28);border-radius:2px;
    background:rgba(243,240,231,.72);
    font-size:17px;letter-spacing:3px;color:#4E594F;font-weight:600;
  }
  .date-chip .pin{width:8px;height:8px;border-radius:50%;background:var(--tertiary);}

  .page-no{
    position:absolute;right:96px;bottom:52px;z-index:25;
    display:flex;align-items:baseline;gap:8px;
    font-size:16px;font-weight:600;letter-spacing:3px;color:#6B756B;
  }
  .page-no .cur{font-family:var(--font-serif);font-size:24px;color:#22302A;letter-spacing:1px;}
  .page-no .line{width:52px;height:1px;background:rgba(27,38,32,.38);margin:0 6px 6px 6px;}
  .bottom-rule{position:absolute;left:96px;bottom:48px;width:1728px;height:1px;background:rgba(27,38,32,.16);}
</style>
</head>
<body>
<main class="slide">
  <div class="bg-field"></div>
  <div class="dot-field dot-a"></div>
  <div class="dot-field dot-b"></div>
  <div class="prism"></div>
  <div class="edge-prism"><span class="p1"></span><span class="p2"></span></div>

  <div class="gridline gl1"></div>
  <div class="gridline gl2"></div>
  <div class="gridline gl3"></div>

  <div class="top-rule"></div>
  <div class="left-rule"></div>
  <div class="rail-tick t1"></div>
  <div class="rail-tick t2"></div>
  <div class="rail-tick t3"></div>

  <div class="top-meta">研究开题评审</div>
  <div class="top-right-meta">虚构测评材料</div>
  <div class="rail-label">虚 构 隔 振 支 架 研 究 · 开 题 汇 报</div>

  <div class="register">
    <div class="r2"></div>
    <div class="r3"></div>
    <div class="r4"></div>
    <div class="r5"></div>
    <div class="dot"></div>
  </div>

  <div class="title-block">
    <div class="kicker"><span class="bar"></span>开题汇报</div>
    <h1>
      <span class="ln">虚构隔振支架</span>
      <span class="ln accent">研究开题</span>
    </h1>
    <div class="subline">
      <span class="rule"></span>
      <span class="sub">研究开题评审汇报</span>
    </div>
    <div class="divider"></div>
  </div>

  <div class="date-chip"><span class="pin"></span>日期：待补充</div>

  <div class="notes">
    <div class="note">
      <div class="n-idx">01</div>
      <div class="n-txt">虚构测评材料：不含已完成实验结论</div>
    </div>
    <div class="note">
      <div class="n-idx">02</div>
      <div class="n-txt">仅依据所提供开题材料，不引入外部事实</div>
    </div>
  </div>

  <div class="bottom-rule"></div>
  <div class="page-no">
    <span class="cur">1</span>
    <span class="line"></span>
    <span>6</span>
  </div>
</main>
</body>
</html>
```
